    val languages: Map<String, String> by lazy { parse(LANGUAGES) }

    /** English script names by ISO 15924 code, as used inside a locale name, e.g. `Hant` → "Traditional". */
    val scripts: Map<String, String> by lazy { parse(SCRIPTS) }

    /** English region names by ISO 3166 or UN M.49 code, e.g. `IN` → "India", `419` → "Latin America". */
    val regions: Map<String, String> by lazy { parse(REGIONS) }

    private fun parse(blob: String): Map<String, String> {
        val parts = blob.split('\u0001')
        val out = LinkedHashMap<String, String>(parts.size / 2)
        var i = 0
        while (i + 1 < parts.size) {
            out[parts[i]] = parts[i + 1]
            i += 2
        }
        return out
    }
